    return api.orders.handle_create({"customer_id": customer_id,
                                     "items": [{"sku": s, "quantity": q} for s, q in items]})


def test_unknown_customer_is_404(shop):
    response = shop.insights.handle_order_history("nobody")
    assert response.status == 404
    assert response.body == {"error": "customer not found"}


def test_customer_with_no_orders_gets_empty_list(shop):
    response = shop.insights.handle_order_history("c1")
    assert response.status == 200
    assert response.body == {"customer_id": "c1", "orders": []}


def test_history_is_newest_first_and_includes_cancelled(shop):
    first = order(shop, "c1", ("BOOK", 1)).body["order_id"]
    other = order(shop, "c2", ("PEN", 1)).body["order_id"]
    second = order(shop, "c1", ("PEN", 2)).body["order_id"]
    shop.orders.handle_cancel(second)
    response = shop.insights.handle_order_history("c1")
    assert response.status == 200
    assert response.body == {"customer_id": "c1", "orders": [
        {"order_id": second, "status": "cancelled", "total_cents": 600},
        {"order_id": first, "status": "placed", "total_cents": 2500},
    ]}
    assert other not in [o["order_id"] for o in response.body["orders"]]


def test_lifetime_value_unknown_customer_is_404(shop):
    response = shop.insights.handle_lifetime_value("nobody")
    assert response.status == 404
    assert response.body == {"error": "customer not found"}


def test_lifetime_value_with_no_orders_is_zero(shop):
    response = shop.insights.handle_lifetime_value("c1")
    assert response.status == 200
    assert response.body == {"customer_id": "c1", "order_count": 0, "lifetime_value_cents": 0}


def test_lifetime_value_excludes_cancelled_and_uses_discounted_totals(shop):
    order(shop, "c2", ("LAMP", 2))                  # gold: 12000 - 1800 = 10200
    cancelled = order(shop, "c2", ("PEN", 4)).body["order_id"]  # 1200, cancelled
    shop.orders.handle_cancel(cancelled)
    order(shop, "c2", ("BOOK", 1))                  # 2500, below threshold
    response = shop.insights.handle_lifetime_value("c2")
    assert response.status == 200
    assert response.body == {"customer_id": "c2", "order_count": 2, "lifetime_value_cents": 12700}


def test_top_customers_ranks_by_value_then_id_and_skips_zero(shop):
    shop.customers.handle_register({"customer_id": "c3", "name": "Linus", "email": "l@example.com"})
    shop.customers.handle_register({"customer_id": "c4", "name": "Nobody", "email": "n@example.com"})
    order(shop, "c1", ("BOOK", 1))                      # 2500
    order(shop, "c1", ("PEN", 1))
    shop.orders.handle_cancel(shop.orders.handle_list_for_customer("c1").body["orders"][1]["order_id"])
    order(shop, "c2", ("LAMP", 2))                      # 10200 (gold)
    order(shop, "c3", ("BOOK", 1))                      # 2500, ties with c1
    response = shop.insights.handle_top_customers(10)
    assert response.status == 200
    assert response.body == {"customers": [
        {"customer_id": "c2", "name": "Grace", "lifetime_value_cents": 10200},
        {"customer_id": "c1", "name": "Ada", "lifetime_value_cents": 2500},
        {"customer_id": "c3", "name": "Linus", "lifetime_value_cents": 2500},
    ]}
    for entry in response.body["customers"]:
        assert shop.insights.handle_lifetime_value(entry["customer_id"]).body["lifetime_value_cents"] == \
            entry["lifetime_value_cents"]


def test_top_customers_respects_limit(shop):
    order(shop, "c1", ("BOOK", 1))
    order(shop, "c2", ("LAMP", 2))
    body = shop.insights.handle_top_customers(1).body
    assert [c["customer_id"] for c in body["customers"]] == ["c2"]


def test_top_customers_with_no_orders_is_empty(shop):
    assert shop.insights.handle_top_customers(5).body == {"customers": []}


